def start_scan(target, scan_type=None, **_extra):
    import json, os, datetime, time, re, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0279000" if __import__("os").path.isdir("./environment_mix/0279000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Usage/audit log (best-effort if collection exists)
    def _log(status, message=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
                "endpoint": "start_scan",
                "status": status,
                "message": message,
                "credential": None,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now
            })
            _save("request_logs.json", logs)

    # Validate target
    if target is None or not isinstance(target, str) or not target.strip():
        _log("error", "VALIDATION_ERROR: target is required")
        return _err("VALIDATION_ERROR", "target is required")
    target = target.strip()
    if len(target) > 2048:
        _log("error", "VALIDATION_ERROR: target too long")
        return _err("VALIDATION_ERROR", "target length must be <= 2048")
    try:
        u = urllib.parse.urlparse(target)
    except Exception:
        _log("error", "VALIDATION_ERROR: invalid URL")
        return _err("VALIDATION_ERROR", "target must be a valid URL")
    if u.scheme not in ("http", "https") or not u.netloc:
        _log("error", "VALIDATION_ERROR: invalid URL scheme/host")
        return _err("VALIDATION_ERROR", "target must be an http(s) URL with a host")

    if scan_type is None:
        scan_type = "full"
    if not isinstance(scan_type, str) or scan_type not in ("passive", "active", "full"):
        _log("error", "VALIDATION_ERROR: invalid scan_type")
        return _err("VALIDATION_ERROR", "scan_type must be one of: passive, active, full")

    # Ambient auth: no credential parameter; only deny if store explicitly indicates scans disabled.
    settings = _load("settings.json")
    if isinstance(settings, dict):
        if settings.get("scans_enabled") is False:
            _log("error", "UNAUTHORIZED: scans disabled")
            return _err("UNAUTHORIZED", "Not permitted to start scans")
        quota = settings.get("scan_quota")
        if isinstance(quota, int) and quota >= 0:
            scans = _load("scans.json")
            if isinstance(scans, list):
                # naive quota: total scans
                if len(scans) >= quota:
                    _log("error", "QUOTA_EXCEEDED: scan quota reached")
                    return _err("QUOTA_EXCEEDED", "Scan quota exceeded")

    scans = _load("scans.json")
    if not isinstance(scans, list):
        scans = []

    # ID generation
    def _new_id(prefix, existing):
        s = {r.get("id") for r in existing if isinstance(r, dict)}
        for _ in range(10000):
            cand = f"{prefix}_{int(time.time()*1000)}_{os.getpid()}_{int(time.time_ns()%1000000)}"
            if cand not in s:
                return cand
        return f"{prefix}_{int(time.time()*1000)}_{os.getpid()}"

    scan_id = _new_id("scan", scans)

    scan_row = {
        "id": scan_id,
        "target_url": target,
        "scan_type": scan_type,
        "status": "queued",
        "progress_pct": 0,
        "started_at": None,
        "completed_at": None,
        "burp_task_ref": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now
    }

    # Enforce unique burp_task_ref where non-null (none here), plus basic constraints already validated.
    scans.append(scan_row)
    _save("scans.json", scans)

    # Upsert scan_targets by canonical_target_url
    canonical = urllib.parse.urlunparse((u.scheme.lower(), u.netloc.lower(), u.path or "/", "", u.query or "", ""))
    host = (u.hostname or "").lower()
    targets = _load("scan_targets.json")
    if not isinstance(targets, list):
        targets = []
    existing = None
    for r in targets:
        if isinstance(r, dict) and r.get("canonical_target_url") == canonical:
            existing = r
            break
    if existing is None:
        tgt_id = _new_id("tgt", targets)
        targets.append({
            "id": tgt_id,
            "canonical_target_url": canonical,
            "host": host,
            "in_scope": True,
            "last_scanned_at": None,
            "created_at": now,
            "updated_at": now
        })
    else:
        # keep existing in_scope; refresh updated_at
        existing["host"] = existing.get("host") or host
        existing["updated_at"] = now
    _save("scan_targets.json", targets)

    _log("ok", None)
    return {"scan": scan_row}

def get_scan_status(scan_id, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0279000" if __import__("os").path.isdir("./environment_mix/0279000") else "/app/database")
