                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, message=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
                "endpoint": "get_scan_status",
                "status": status,
                "message": message,
                "credential": None,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now
            })
            _save("request_logs.json", logs)

    if scan_id is None or not isinstance(scan_id, str) or not scan_id.strip():
        _log("error", "VALIDATION_ERROR: scan_id is required")
        return _err("VALIDATION_ERROR", "scan_id is required")
    scan_id = scan_id.strip()
    if len(scan_id) > 256:
        _log("error", "VALIDATION_ERROR: scan_id malformed")
        return _err("VALIDATION_ERROR", "scan_id is malformed")

    settings = _load("settings.json")
    if isinstance(settings, dict) and settings.get("scans_readable") is False:
        _log("error", "UNAUTHORIZED: scans not accessible")
        return _err("UNAUTHORIZED", "Not permitted to access scans")

    scans = _load("scans.json")
    if not isinstance(scans, list):
        scans = []

    row = None
    for r in scans:
        if isinstance(r, dict) and r.get("id") == scan_id:
            row = r
            break

    if row is None:
        _log("error", "NOT_FOUND: scan not found")
        return _err("NOT_FOUND", "No scan exists with the given scan_id", scan_id=scan_id)

    _log("ok", None)
    return {"scan": row}

def get_scan_issues(scan_id, severity=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0279000" if __import__("os").path.isdir("./environment_mix/0279000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, message=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
                "endpoint": "get_scan_issues",
                "status": status,
                "message": message,
                "credential": None,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now
            })
            _save("request_logs.json", logs)

    if scan_id is None or not isinstance(scan_id, str) or not scan_id.strip():
        _log("error", "VALIDATION_ERROR: scan_id is required")
        return _err("VALIDATION_ERROR", "scan_id is required")
    scan_id = scan_id.strip()
    if len(scan_id) > 256:
        _log("error", "VALIDATION_ERROR: scan_id malformed")
        return _err("VALIDATION_ERROR", "scan_id is malformed")

    allowed = {"high", "medium", "low", "info", "all"}
    if severity is None:
        severity = "all"
    if not isinstance(severity, str) or severity not in allowed:
        _log("error", "VALIDATION_ERROR: invalid severity")
        return _err("VALIDATION_ERROR", "severity must be one of: high, medium, low, info, all")

    settings = _load("settings.json")
    if isinstance(settings, dict) and settings.get("scans_readable") is False:
        _log("error", "UNAUTHORIZED: scans not accessible")
        return _err("UNAUTHORIZED", "Not permitted to access scans")

    scans = _load("scans.json")
    if not isinstance(scans, list):
        scans = []
    if not any(isinstance(r, dict) and r.get("id") == scan_id for r in scans):
        _log("error", "NOT_FOUND: scan not found")
        return _err("NOT_FOUND", "No scan exists with the given scan_id", scan_id=scan_id)

    issues = _load("scan_issues.json")
    if not isinstance(issues, list):
        issues = []

    out = []
    for r in issues:
        if not isinstance(r, dict):
            continue
        if r.get("scan_id") != scan_id:
            continue
        if severity != "all" and r.get("severity") != severity:
            continue
        out.append(r)

    # Service default cap (not pageable)
    default_cap = 200
    if isinstance(settings, dict) and isinstance(settings.get("scan_issues_default_limit"), int):
        default_cap = max(1, min(2000, settings["scan_issues_default_limit"]))
    out = out[:default_cap]

    _log("ok", None)
    return {"issues": out, "count": len(out)}

def get_proxy_history(host=None, method=None, status_code=None, limit=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0279000" if __import__("os").path.isdir("./environment_mix/0279000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "get_proxy_history"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status, **extra):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        row.update(extra or {})
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate inputs
    if host is not None:
        if not isinstance(host, str):
            out = _err("VALIDATION_ERROR", "host must be a string when provided", field="host")
            _log(out["error"]["code"], error=out["error"])
            return out
        host = host.strip()
        if host == "":
            out = _err("VALIDATION_ERROR", "host must be a non-empty string when provided", field="host")
            _log(out["error"]["code"], error=out["error"])
            return out

    if method is not None:
        if not isinstance(method, str):
            out = _err("VALIDATION_ERROR", "method must be a string when provided", field="method")
            _log(out["error"]["code"], error=out["error"])
            return out
        method = method.strip()
        if not (1 <= len(method) <= 16):
            out = _err("VALIDATION_ERROR", "method length must be between 1 and 16", field="method")
            _log(out["error"]["code"], error=out["error"])
            return out
        # HTTP token validation (per tool description)
        if not re.fullmatch(r"[A-Za-z0-9!#$%&'*+\-.^_`|~]+", method):
            out = _err("VALIDATION_ERROR", "method must be a valid HTTP token", field="method")
            _log(out["error"]["code"], error=out["error"])
            return out

    if status_code is not None:
        # Business rule: must be integer in [100, 599]; non-integers rejected even if schema says number
        if isinstance(status_code, bool) or not isinstance(status_code, (int, float)):
            out = _err("VALIDATION_ERROR", "status_code must be an integer between 100 and 599", field="status_code")
            _log(out["error"]["code"], error=out["error"])
            return out
        if isinstance(status_code, float) and not status_code.is_integer():
            out = _err("VALIDATION_ERROR", "status_code must be an integer between 100 and 599", field="status_code")
            _log(out["error"]["code"], error=out["error"])
            return out
        status_code = int(status_code)
        if not (100 <= status_code <= 599):
            out = _err("VALIDATION_ERROR", "status_code must be between 100 and 599", field="status_code")
            _log(out["error"]["code"], error=out["error"])
            return out

    if limit is None:
        limit = 10
    else:
        if isinstance(limit, bool) or not isinstance(limit, (int, float)):
            out = _err("VALIDATION_ERROR", "limit must be a valid number", field="limit")
            _log(out["error"]["code"], error=out["error"])
            return out
        if isinstance(limit, float) and not limit.is_integer():
            out = _err("VALIDATION_ERROR", "limit must be a whole number", field="limit")
            _log(out["error"]["code"], error=out["error"])
            return out
        limit = int(limit)
    # Clamp 1..200
    if limit < 1:
        limit = 1
    if limit > 200:
        limit = 200

    rows = _load("proxy_history.json")
    if not isinstance(rows, list):
        rows = []

    def _dt_key(v):
        if not isinstance(v, str):
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    filtered = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        if host is not None and r.get("host") != host:
            continue
        if method is not None and r.get("method") != method:
            continue
        if status_code is not None:
            sc = r.get("status_code")
            if sc is None:
                continue
            if isinstance(sc, (int, float)) and not isinstance(sc, bool):
                if int(sc) != status_code:
                    continue
            else:
                continue
        filtered.append(r)

    filtered.sort(key=lambda x: _dt_key(x.get("captured_at")), reverse=True)
    items = filtered[:limit]

    out = {
        "entries": items,
        "count": len(items),
        "limit": limit,
        "filters": {"host": host, "method": method, "status_code": status_code},
    }
    _log("OK", returned=len(items))
    return out

