def list_scans(status=None, target_url=None, host=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, urllib.parse, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0279000" if __import__("os").path.isdir("./environment_mix/0279000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "list_scans",
            "credential_id": credential_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _ambient_authorized():
        candidates = []
        for fn in ("api_keys.json", "credentials.json", "auth.json", "users.json", "workspaces.json", "accounts.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                candidates.append(fn)
        if not candidates:
            return True, None
        for fn in candidates:
            rows = _load(fn)
            for r in rows if isinstance(rows, list) else []:
                if isinstance(r, dict):
                    if r.get("revoked") is True or r.get("disabled") is True:
                        continue
                    if r.get("status") in ("revoked", "disabled", "inactive"):
                        continue
                    return True, r.get("id")
        return False, None

    ok_auth, cred_id = _ambient_authorized()
    if not ok_auth:
        _log("error", credential_id=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not permitted to list scans.")

    allowed_status = {"queued", "running", "completed", "failed", "cancelled", "all"}
    if status is None:
        status = "all"
    if not isinstance(status, str) or status not in allowed_status:
        _log("error", credential_id=cred_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status filter.", allowed=list(sorted(allowed_status)))

    if target_url is not None and not isinstance(target_url, str):
        _log("error", credential_id=cred_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "target_url must be a string.")
    if host is not None and not isinstance(host, str):
        _log("error", credential_id=cred_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "host must be a string.")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return "BAD"
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return "BAD"

    ca = _parse_rfc3339(created_after)
    if ca == "BAD":
        _log("error", credential_id=cred_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "created_after must be an RFC3339 timestamp.")
    cb = _parse_rfc3339(created_before)
    if cb == "BAD":
        _log("error", credential_id=cred_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "created_before must be an RFC3339 timestamp.")
    if ca and cb and ca > cb:
        _log("error", credential_id=cred_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "created_after must be <= created_before.")

    if limit is None:
        limit_i = 50
    else:
        if not isinstance(limit, int) or isinstance(limit, bool):
            _log("error", credential_id=cred_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer.")
        limit_i = limit
    if limit_i < 1:
        limit_i = 1
    if limit_i > 200:
        limit_i = 200

    # Cursor: opaque; we use base64 of ISO created_at + "|" + id
    start_after = None
    if cursor is not None:
        if not isinstance(cursor, str) or cursor == "":
            _log("error", credential_id=cred_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            raw_s = raw.decode("utf-8")
            parts = raw_s.split("|", 1)
            if len(parts) != 2:
                raise ValueError("bad cursor")
            c_dt = _parse_rfc3339(parts[0])
            if c_dt == "BAD":
                raise ValueError("bad cursor dt")
            start_after = (c_dt, parts[1])
        except Exception:
            _log("error", credential_id=cred_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    scans = _load("scans.json")
    if not isinstance(scans, list):
        scans = []

    def _created_dt(r):
        s = r.get("created_at")
        try:
            return datetime.datetime.fromisoformat(str(s).replace("Z", "+00:00"))
        except Exception:
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    def _host_from_url(u):
        try:
            p = urllib.parse.urlparse(u)
            return p.hostname
        except Exception:
            return None

    filtered = []
    for r in scans:
        if not isinstance(r, dict):
            continue
        if status != "all" and r.get("status") != status:
            continue
        if target_url is not None and r.get("target_url") != target_url:
            continue
        if host is not None:
            h = _host_from_url(r.get("target_url") or "")
            if h != host:
                continue
        cdt = _created_dt(r)
        if ca and cdt <= ca:
            continue
        if cb and cdt >= cb:
            continue
        filtered.append(r)

    # Order by created_at desc; tie-breaker by id desc for stable pagination
    filtered.sort(key=lambda r: (_created_dt(r), str(r.get("id") or "")), reverse=True)

    # Apply cursor (start after cursor item)
    if start_after is not None:
        cdt, cid = start_after
        tmp = []
        for r in filtered:
            rd = _created_dt(r)
            rid = str(r.get("id") or "")
            # keep items strictly older (or same created_at but id < cursor id in desc ordering)
            if rd < cdt:
                tmp.append(r)
            elif rd == cdt and rid < cid:
                tmp.append(r)
        filtered = tmp

    total = len(filtered)
    page = filtered[:limit_i]
    has_more = total > len(page)

    next_cursor = None
    if page:
        last = page[-1]
        dt_s = (last.get("created_at") or "")
        if not isinstance(dt_s, str):
            dt_s = ""
        raw = f"{dt_s}|{str(last.get('id') or '')}".encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=") if has_more else None

    _log("ok", credential_id=cred_id)
    return {
        "items": page,
        "total": total,
        "limit": limit_i,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

def update_scan(scan_id, status=None, progress_pct=None, error_message=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0279000" if __import__("os").path.isdir("./environment_mix/0279000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _log(status_s, credential_id=None, error_code=None, scan_id_v=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "update_scan",
            "credential_id": credential_id,
            "status": status_s,
            "error_code": error_code,
            "scan_id": scan_id_v,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _ambient_authorized():
        candidates = []
        for fn in ("api_keys.json", "credentials.json", "auth.json", "users.json", "workspaces.json", "accounts.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                candidates.append(fn)
        if not candidates:
            return True, None
        for fn in candidates:
            rows = _load(fn)
            for r in rows if isinstance(rows, list) else []:
                if isinstance(r, dict):
                    if r.get("revoked") is True or r.get("disabled") is True:
                        continue
                    if r.get("status") in ("revoked", "disabled", "inactive"):
                        continue
                    return True, r.get("id")
        return False, None

    ok_auth, cred_id = _ambient_authorized()
    if not ok_auth:
        _log("error", credential_id=None, error_code="UNAUTHORIZED", scan_id_v=scan_id)
        return _err("UNAUTHORIZED", "Not permitted to update scans.")

    if not isinstance(scan_id, str) or not scan_id:
        _log("error", credential_id=cred_id, error_code="VALIDATION_ERROR", scan_id_v=scan_id)
        return _err("VALIDATION_ERROR", "scan_id must be a non-empty string.")

    allowed_status = {"queued", "running", "completed", "failed", "cancelled"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _log("error", credential_id=cred_id, error_code="VALIDATION_ERROR", scan_id_v=scan_id)
        return _err("VALIDATION_ERROR", "Invalid status.", allowed=list(sorted(allowed_status)))

    if progress_pct is not None:
        if not isinstance(progress_pct, int) or isinstance(progress_pct, bool):
            _log("error", credential_id=cred_id, error_code="VALIDATION_ERROR", scan_id_v=scan_id)
            return _err("VALIDATION_ERROR", "progress_pct must be an integer.")
        if progress_pct < 0 or progress_pct > 100:
            _log("error", credential_id=cred_id, error_code="VALIDATION_ERROR", scan_id_v=scan_id)
            return _err("VALIDATION_ERROR", "progress_pct must be between 0 and 100.")

    if error_message is not None and not isinstance(error_message, str):
        _log("error", credential_id=cred_id, error_code="VALIDATION_ERROR", scan_id_v=scan_id)
        return _err("VALIDATION_ERROR", "error_message must be a string when provided.")

    scans = _load("scans.json")
    if not isinstance(scans, list):
        scans = []

    idx = None
    for i, r in enumerate(scans):
        if isinstance(r, dict) and r.get("id") == scan_id:
            idx = i
            break
    if idx is None:
        _log("error", credential_id=cred_id, error_code="NOT_FOUND", scan_id_v=scan_id)
        return _err("NOT_FOUND", "Scan not found.", scan_id=scan_id)

    scan = scans[idx]
    old_status = scan.get("status")

    transitions = {
        "queued": ["running", "cancelled", "failed"],
        "running": ["completed", "failed", "cancelled"],
        "completed": [],
        "failed": [],
        "cancelled": [],
    }

    # Validate immutable fields aren't being changed (only status/progress_pct/error_message accepted already)
    # Enforce transition rules if status is provided and changes
    if status is not None and status != old_status:
        if old_status not in transitions or status not in transitions.get(old_status, []):
            _log("error", credential_id=cred_id, error_code="INVALID_TRANSITION", scan_id_v=scan_id)
            return _err(
                "INVALID_TRANSITION",
                f"Illegal status transition from {old_status} to {status}.",
                from_status=old_status,
                to_status=status,
            )

    # Enforce completed_at/progress rules
    if status == "completed":
        if progress_pct is not None and progress_pct != 100:
            _log("error", credential_id=cred_id, error_code="VALIDATION_ERROR", scan_id_v=scan_id)
            return _err("VALIDATION_ERROR", "progress_pct cannot be set when status is completed (forced to 100).")
    if status in ("failed", "cancelled"):
        # allowed <=100 already; no extra
        pass

    # Apply updates
    changed = False
    if status is not None and status != old_status:
        scan["status"] = status
        changed = True

        if status == "running":
            # started_at set if missing
            if not scan.get("started_at"):
                scan["started_at"] = now
            # completed_at must be null while running
            scan["completed_at"] = None

            # Upsert scan_targets by canonical_target_url (target_url) and host.
            targets = _load("scan_targets.json")
            if not isinstance(targets, list):
                targets = []
            canonical = scan.get("target_url")
            host_val = None
            try:
                import urllib.parse
                host_val = urllib.parse.urlparse(canonical or "").hostname
            except Exception:
                host_val = None
            if canonical and isinstance(canonical, str):
                tgt_idx = None
                for j, t in enumerate(targets):
                    if isinstance(t, dict) and t.get("canonical_target_url") == canonical:
                        tgt_idx = j
                        break
                if tgt_idx is None:
                    # create new target
                    tid = f"tgt_{int(time.time()*1000)}_{len(targets)+1}"
                    targets.append({
                        "id": tid,
                        "canonical_target_url": canonical,
                        "host": host_val or "",
                        "in_scope": True,
                        "last_scanned_at": now,
                        "created_at": now,
                        "updated_at": now,
                    })
                else:
                    trow = targets[tgt_idx]
                    trow["host"] = trow.get("host") or (host_val or "")
                    trow["last_scanned_at"] = now
                    if "in_scope" not in trow:
                        trow["in_scope"] = True
                    trow["updated_at"] = now
                _save("scan_targets.json", targets)

        if status in ("completed", "failed", "cancelled"):
            scan["completed_at"] = now
            if status == "completed":
                scan["progress_pct"] = 100
            else:
                # keep <=100, if missing set to min(existing,100) else as-is
                try:
                    pp = int(scan.get("progress_pct", 0))
                except Exception:
                    pp = 0
                scan["progress_pct"] = max(0, min(100, pp))

    # Progress update rules depending on resulting status
    resulting_status = scan.get("status")
    if progress_pct is not None:
        if resulting_status == "completed":
            _log("error", credential_id=cred_id, error_code="VALIDATION_ERROR", scan_id_v=scan_id)
            return _err("VALIDATION_ERROR", "Cannot update progress_pct when scan is completed.")
        # allowed for queued/running/failed/cancelled (<=100 already ensured)
        if scan.get("progress_pct") != progress_pct:
            scan["progress_pct"] = progress_pct
            changed = True

    if error_message is not None:
        if scan.get("error_message") != error_message:
            scan["error_message"] = error_message
            changed = True

    # Enforce constraints for completed_at nullness
    if scan.get("status") in ("queued", "running"):
        scan["completed_at"] = None
    if scan.get("status") in ("completed", "failed", "cancelled"):
        if not scan.get("completed_at"):
            scan["completed_at"] = now

    if not changed:
        # No success without effect: if nothing changed, treat as conflict-free idempotent? Spec doesn't say.
        # We'll return the existing record (idempotent update) only if provided fields match current state.
        _log("ok", credential_id=cred_id, scan_id_v=scan_id)
        return {"scan": scan}

    scan["updated_at"] = now
    scans[idx] = scan
    _save("scans.json", scans)

    _log("ok", credential_id=cred_id, scan_id_v=scan_id)
    return {"scan": scan}

