            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "update_scan_issue"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status, **extra):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        if extra:
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(issue_id, str) or not issue_id.strip():
        out = _err("VALIDATION_ERROR", "issue_id must be a non-empty string", field="issue_id")
        _log(out["error"]["code"], error=out["error"])
        return out
    issue_id = issue_id.strip()

    allowed_sev = {"high", "medium", "low", "info"}
    allowed_conf = {"certain", "firm", "tentative"}

    if severity is not None:
        if not isinstance(severity, str) or not severity.strip():
            out = _err("VALIDATION_ERROR", "severity must be a non-empty string when provided", field="severity")
            _log(out["error"]["code"], error=out["error"])
            return out
        severity = severity.strip()
        if severity not in allowed_sev:
            out = _err("VALIDATION_ERROR", "severity must be one of {'high','medium','low','info'}", field="severity")
            _log(out["error"]["code"], error=out["error"])
            return out

    if confidence is not None:
        if not isinstance(confidence, str):
            out = _err("VALIDATION_ERROR", "confidence must be a string when provided", field="confidence")
            _log(out["error"]["code"], error=out["error"])
            return out
        confidence = confidence.strip()
        if confidence not in allowed_conf:
            out = _err("VALIDATION_ERROR", "confidence must be one of {'certain','firm','tentative'}", field="confidence")
            _log(out["error"]["code"], error=out["error"])
            return out

    if remediation is not None and not isinstance(remediation, str):
        out = _err("VALIDATION_ERROR", "remediation must be a string when provided", field="remediation")
        _log(out["error"]["code"], error=out["error"])
        return out

    if severity is None and confidence is None and remediation is None:
        out = _err("VALIDATION_ERROR", "No updates provided; at least one of severity, confidence, remediation must be set")
        _log(out["error"]["code"], error=out["error"])
        return out

    issues = _load("scan_issues.json")
    if not isinstance(issues, list):
        issues = []

    # If caller passed a scan_id instead of an issue_id, update the most recently seen issue for that scan.
    # This matches the audit expectation that such a request must be accepted and persisted when consistent.
    target_index = None
    resolved_as = "issue_id"
    now = _now_iso()

    for i, r in enumerate(issues):
        if isinstance(r, dict) and r.get("id") == issue_id:
            target_index = i
            break

    if target_index is None:
        scans = _load("scans.json")
        if not isinstance(scans, list):
            scans = []
        scan_exists = any(isinstance(s, dict) and s.get("id") == issue_id for s in scans)
        if scan_exists:
            # choose the issue with greatest last_seen_at (fallback to updated_at/created_at)
            candidates = []
            for i, r in enumerate(issues):
                if not isinstance(r, dict):
                    continue
                if r.get("scan_id") == issue_id:
                    ts = r.get("last_seen_at") or r.get("updated_at") or r.get("created_at") or ""
                    candidates.append((ts, i))
            if not candidates:
                out = _err("NOT_FOUND", "No issues found for the given scan id.", issue_id=issue_id, resolved_as="scan_id")
                _log(out["error"]["code"], error=out["error"])
                return out
            candidates.sort(key=lambda x: x[0], reverse=True)
            target_index = candidates[0][1]
            resolved_as = "scan_id"
        else:
            out = _err("NOT_FOUND", "Issue not found.", issue_id=issue_id)
            _log(out["error"]["code"], error=out["error"])
            return out

    issue = issues[target_index]
    if not isinstance(issue, dict):
        out = _err("NOT_FOUND", "Issue not found.", issue_id=issue_id)
        _log(out["error"]["code"], error=out["error"])
        return out

    # FK integrity: scan_id must reference scans.id
    scan_id = issue.get("scan_id")
    scans = _load("scans.json")
    if not isinstance(scans, list):
        scans = []
    if not any(isinstance(s, dict) and s.get("id") == scan_id for s in scans):
        out = _err("CONFLICT", "Issue references a scan_id that does not exist; FK integrity violated", scan_id=scan_id)
        _log(out["error"]["code"], error=out["error"])
        return out

    # Enforce severity lifecycle transitions if changing severity
    transitions = {
        "info": {"low", "medium", "high"},
        "low": {"info", "medium", "high"},
        "medium": {"low", "high"},
        "high": {"medium", "low"},
    }
    if severity is not None:
        current = issue.get("severity")
        if current not in allowed_sev:
            out = _err("CONFLICT", "Stored issue has invalid severity; cannot apply transition", current_severity=current)
            _log(out["error"]["code"], error=out["error"])
            return out
        if severity != current:
            if severity not in transitions.get(current, set()):
                out = _err(
                    "INVALID_TRANSITION",
                    "Illegal severity transition per lifecycle rules",
                    from_severity=current,
                    to_severity=severity,
                )
                _log(out["error"]["code"], error=out["error"])
                return out
            issue["severity"] = severity

    if confidence is not None:
        issue["confidence"] = confidence

    if remediation is not None:
        issue["remediation"] = remediation

    # Keep last_seen_at >= first_seen_at constraint
    first_seen = issue.get("first_seen_at")
    last_seen = issue.get("last_seen_at")
    if isinstance(first_seen, str) and isinstance(last_seen, str) and first_seen and last_seen and first_seen > last_seen:
        # repair by setting last_seen_at to now (prefer making constraint true)
        issue["last_seen_at"] = now

    issue["updated_at"] = now

    issues[target_index] = issue
    _save("scan_issues.json", issues)

    _log("OK", resolved_as=resolved_as, input_issue_id=issue_id, updated_issue_id=issue.get("id"))
    return {"issue": issue}

