            break

    if entry is None:
        out = _err("NOT_FOUND", "Proxy history entry not found (may have been purged)", id=rid)
        _log(out["error"]["code"], error=out["error"], proxy_history_id=rid)
        return out

    # Return the stored record as-is (including any truncated bodies already stored)
    resp = {"entry": entry}
    _log("OK", proxy_history_id=rid)
    return resp

def get_current_user(include_quota=None, include_scopes=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0279000" if __import__("os").path.isdir("./environment_mix/0279000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "get_current_user"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status, **extra):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        row.update(extra or {})
        logs.append(row)
        _save("request_logs.json", logs)

    if include_quota is None:
        include_quota = True
    if include_scopes is None:
        include_scopes = True

    if not isinstance(include_quota, bool):
        out = _err("VALIDATION_ERROR", "include_quota must be boolean", field="include_quota")
        _log(out["error"]["code"], error=out["error"])
        return out
    if not isinstance(include_scopes, bool):
        out = _err("VALIDATION_ERROR", "include_scopes must be boolean", field="include_scopes")
        _log(out["error"]["code"], error=out["error"])
        return out

    # Ambient authentication: this tool has no credential parameter, so resolve a plausible active identity.
    # Search across common auth-ish collections if present; otherwise treat as local user.
    identity = {
        "id": "local_user",
        "type": "user",
        "display_name": "Local User",
        "active": True,
    }
    scopes = ["scans:read", "scans:write", "issues:read", "issues:write", "proxy:read", "sitemap:read"]

    # Try to find any active principal row (do not fail if files absent)
    auth_files = ("credentials.json", "api_keys.json", "users.json", "accounts.json", "workspaces.json", "auth.json")
    for fn in auth_files:
        p = os.path.join(_DB, fn)
        if not os.path.exists(p):
            continue
        rows = _load(fn)
        if isinstance(rows, dict) and "data" in rows and isinstance(rows["data"], list):
            rows = rows["data"]
        if not isinstance(rows, list):
            continue
        for r in rows:
            if not isinstance(r, dict):
                continue
            if r.get("revoked") is True or r.get("disabled") is True:
                continue
            if r.get("status") in ("revoked", "disabled", "inactive"):
                continue
            rid = r.get("id")
            if isinstance(rid, str) and rid.strip():
                identity = {
                    "id": rid,
                    "type": r.get("type") or ("api_key" if "key" in r or "token" in r else "user"),
                    "display_name": r.get("name") or r.get("email") or r.get("label") or "Authenticated User",
                    "active": True,
                }
                if isinstance(r.get("scopes"), list) and all(isinstance(s, str) for s in r.get("scopes")):
                    scopes = r["scopes"]
                break
        if identity.get("id") != "local_user":
            break

    quota = None
    if include_quota:
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)
        # naive counters from request logs (service-dynamics observable)
        def _parse_ts(v):
            if not isinstance(v, str):
                return None
            s = v.strip()
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt
            except Exception:
                return None

        last_min = 0
        last_hour = 0
        last_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_ts(r.get("timestamp") or r.get("created_at"))
            if ts is None:
                continue
            delta = (now - ts).total_seconds()
            if 0 <= delta <= 60:
                last_min += 1
            if 0 <= delta <= 3600:
                last_hour += 1
            if 0 <= delta <= 86400:
                last_day += 1

        quota = {
            "requests_last_minute": last_min,
            "requests_last_hour": last_hour,
            "requests_last_day": last_day,
            "limits": {
                "rate_limit_per_minute": None,
                "quota_per_day": None,
            },
        }

    resp = {"user": identity}
    if include_scopes:
        resp["scopes"] = scopes
    if include_quota:
        resp["quota"] = quota

    _log("OK", user_id=identity.get("id"))
    return resp
